  "id": "PLAN-RELEASE-REARCHITECTURE-008-013",
  "status": "draft",
  "goal": "Implement the version-1 durable release architecture as a safe, deterministic path from release decision through intent, trust, graph capability, crash-safe execution, and CLI/CI migration, without allowing existing PublishPlan routes to authorize effects.",
  "specs": [
    { "id": "SPEC-RELEASE-DECISION-008", "file": ".claude/specs/SPEC-RELEASE-DECISION-008.json", "sha256": "90e1c3bf5dd68d6e7cb04f5cfcb2ec0add783911b0bf45592d0d7dae0106d371" },
    { "id": "SPEC-RELEASE-INTENT-MODEL-009", "file": ".claude/specs/SPEC-RELEASE-INTENT-MODEL-009.json", "sha256": "e51fb1a54d505186dac60575495c18df13688994ef3f19c19df7b6feeb3090ea" },
    { "id": "SPEC-RELEASE-TRUST-010", "file": ".claude/specs/SPEC-RELEASE-TRUST-010.json", "sha256": "9be173c2cc28dbf5a76d449e23513dd81e297ae7bd9ae22b5b8b557cbf5a9ac2" },
    { "id": "SPEC-RELEASE-CAPABILITY-011", "file": ".claude/specs/SPEC-RELEASE-CAPABILITY-011.json", "sha256": "d5838a53afd8e3b62326e754a4c9bffb5fdc17169329ad23d8e6b2e690cbcd3d" },
    { "id": "SPEC-RELEASE-EXECUTION-012", "file": ".claude/specs/SPEC-RELEASE-EXECUTION-012.json", "sha256": "aab151ef46ff5c1932bd523f22b818d8cb5d07b0bd1013331e243ef68e74b855" },
    { "id": "SPEC-RELEASE-INTERFACES-013", "file": ".claude/specs/SPEC-RELEASE-INTERFACES-013.json", "sha256": "bb53ab64e15cfdeaff4bae8ce7dc652cef771dce17b82f5c9c8e126c51163378" }
  ],
  "linked_requirement": null,
  "requirement_note": "No requirement@1 records exist for these REQ-less release specs. This plan is deliberately linked directly to the six specs; requirement backfill is a repository-process task and must not be fabricated here.",
  "architecture": "The dependency direction is strict: graph computes the policy decision; model owns only serializable typed identities, canonical transcripts, durable intent/state/receipt schemas; vcs owns fresh Git trust and lock evidence; graph turns a durable intent plus fresh observation into an opaque capability containing private prepared inputs; the ordered executor consumes that capability and ApplyPermit; CLI and CI are adapters. Layer 1 never depends on graph/vcs/providers, and no generic fingerprint, raw config bytes, endpoint, credential, workspace path, provider output, PublishPlan, or cache becomes durable authority.",
  "tech_stack": ["Rust stable", "BTreeMap/BTreeSet and explicit canonical keys", "sha2", "serde/schemars", "miette", "callisto_model::atomic::atomic_write", "callisto-vcs structured Git API", "standards-compliant url parser in callisto-graph", "OS-backed advisory lock crate only after API review", "just", "moon"],
  "execution_rules": {
    "tdd": "Every behavior-changing task starts with a focused RED test or a documented regression-proof test when the preceding task already implements the behavior. GREEN is followed by the named moon/just verification. Never introduce a temporary unsafe implementation merely to make a test red.",
    "ordering": "Batches execute in order. Tasks within a batch may run in parallel only when their files and public APIs do not overlap; integration tasks wait for all predecessors. No provider effect code starts before capability, state, and observation contracts are green.",
    "commits": "Commit only one verified semantic interval at a time using the task's conventional commit. Do not combine model, VCS, graph, executor, and interface changes in one commit.",
    "verification": "Use moon or just for Rust verification: moon run callisto-model:test, moon run callisto-vcs:test, moon run callisto-graph:test, moon run callisto-cli:test, just fmt-check, just lint, just test, and just ci. Focused test filtering is configured through the task runner where available; raw cargo commands are not the acceptance verification path.",
    "gates": "After each batch, run an independent mutation/review gate. The final exit gate re-reads all specs, maps every AC to tests/code, runs just ci, checks release routes structurally, and verifies the worktree is limited to planned files plus intentionally added tests/docs/workflow files."
  },
  "prototype_disposition": {
    "rule": "Before T01, inventory every uncommitted or prior foundation/prototype release file against these six specs. Retain only code that passes the task's RED/GREEN tests without weakening its assertions; otherwise delete it or revert it in the same semantic interval before new implementation begins.",
    "known_rejections": ["Do not retain generic ReleaseInputComponentV1 kind/fingerprint fields or raw configuration-byte hashing.", "Do not retain graph validation based on a cached Workspace, caller-supplied SHA, manual registry URL parsing, or a capability lacking per-operation prepared inputs.", "Do not retain executor logic where !is_failure or absence of a record implies success.", "Do not retain PublishPlan/PLAN_JSON as a durable intent, identity, or mutation authority."],
    "verification": "Record the inventory and disposition in the task commit body or a test-only comment; `git diff --check` and targeted tests must pass after cleanup."
  },
  "batches": [
    { "id": "B0-baseline", "depends_on": [], "task_ids": ["T00"], "description": "Inventory/discard unsafe prototypes and establish a clean TDD baseline." },
    { "id": "B1-decision", "depends_on": ["B0-baseline"], "task_ids": ["T01", "T02"], "description": "Graph-owned deterministic release roster and explanations." },
    { "id": "B2-intent-model", "depends_on": ["B1-decision"], "task_ids": ["T03", "T04"], "description": "Layer-1 typed durable decision/intent, bindings, DAG, artifact slots, and canonical validation." },
    { "id": "B3-trust", "depends_on": ["B2-intent-model"], "task_ids": ["T05"], "description": "VCS-owned clean detached Git evidence and workspace exclusion lock." },
    { "id": "B4-capability", "depends_on": ["B1-decision", "B2-intent-model", "B3-trust"], "task_ids": ["T06", "T07"], "description": "Fresh graph re-observation, safe endpoint preparation, and opaque validated authority." },
    { "id": "B5-execution", "depends_on": ["B4-capability"], "task_ids": ["T08", "T09", "T10"], "description": "Atomic state/receipt, observation-driven reconciliation, provider adapter contracts, and artifact-manifest binding." },
    { "id": "B6-interfaces", "depends_on": ["B5-execution"], "task_ids": ["T11", "T12", "T13"], "description": "CLI migration, GitHub plan/build/execute topology, docs, and removal of legacy mutation authority." },
    { "id": "B7-exit", "depends_on": ["B6-interfaces"], "task_ids": ["T14"], "description": "Independent mutation, security, and spec-compliance exit gate." }
  ],
  "tasks": [
    {
      "id": "T00", "batch_id": "B0-baseline", "depends_on": [], "kind": "baseline", "covers": [],
      "description": "Inventory the existing model/graph/VCS/reconciliation prototypes and discard or isolate every implementation that violates the new typed-boundary contract before extending it.",
      "files": ["crates/callisto-model/src/release.rs", "crates/callisto-graph/src/commands/release.rs", "crates/callisto-vcs/src/lib.rs"],
      "red": "Add characterization tests proving generic raw fingerprint acceptance, cached-workspace acceptance, caller-supplied source substitution, manual URL acceptance, and absence-of-failure success are rejected by the intended new public boundaries; record which tests reveal prototype violations.",
      "green": "Remove/replace rejected prototype paths; preserve only existing code that meets the characterization contract without compatibility shims granting authority.",
      "verify": ["just fmt-check", "just lint", "moon run callisto-model:test", "moon run callisto-graph:test", "moon run callisto-vcs:test"],
      "commit": "chore(release): remove unsafe durable-release prototypes"
    },
    {
      "id": "T01", "batch_id": "B1-decision", "depends_on": ["T00"], "kind": "implementation", "covers": ["008:AC-001", "008:AC-002", "008:AC-003", "008:AC-004", "008:AC-006", "008:AC-007"],
      "description": "Add graph-owned ReleaseDecisionV1 derivation from exact qualified CLI selection or a named configuration-selection mode and fresh configuration/discovery, including non-overlapping linked-group closure, configured fixed-group/cascade/prerelease rules, exact qualified roster entries, target versions, and closed inclusion reasons.",
      "files": ["crates/callisto-graph/src/commands/release_decision.rs", "crates/callisto-graph/src/error.rs", "crates/callisto-graph/tests/release_decision_test.rs"],
      "red": "Table tests first: exact CLI selection, named configuration selection, overlapping linked-group configuration rejection, fixed/cascade expansion, prerelease off-roster exclusion, empty selection rejection, conflicting target versions, same bare name across ecosystems, and safe miette diagnostics.",
      "green": "Implement using existing group/cascade/prerelease semantics only; emit a serializable graph result without PublishPlan dependency or effects.",
      "verify": ["moon run callisto-graph:test", "just fmt-check", "just lint"],
      "commit": "feat(graph): derive explicit durable release decisions"
    },
    {
      "id": "T02", "batch_id": "B1-decision", "depends_on": ["T01"], "kind": "determinism", "covers": ["008:AC-005"],
      "description": "Define decision canonical ordering and DecisionDigest transcript, independent of discovery order, HashMap iteration, enum declaration order, source formatting, and wall clock.",
      "files": ["crates/callisto-graph/src/commands/release_decision.rs", "crates/callisto-graph/tests/release_decision_test.rs", "crates/callisto-model/src/release.rs"],
      "red": "Permutation tests reorder packages, groups, edges, and reasons and assert byte-identical canonical decision data/digest; a targeted DepKind declaration-order regression proves the explicit semantic key is used.",
      "green": "Use BTree collections or documented sorted vectors and the versioned length-prefixed transcript primitive; do not serialize Debug/Ord output as authority.",
      "verify": ["moon run callisto-model:test", "moon run callisto-graph:test", "just fmt-check", "just lint"],
      "commit": "feat(release): canonicalize durable release decisions"
    },
    {
      "id": "T03", "batch_id": "B2-intent-model", "depends_on": ["T02"], "kind": "model", "covers": ["009:AC-001", "009:AC-002", "009:AC-004", "009:AC-005", "009:AC-006", "009:AC-008"],
      "description": "Replace broad release-intent prototype fields with closed Layer-1 semantic snapshot types, exact ReleaseOperationId variants, explicit prerequisite DAG, artifact slots, strict schema validation, and IntentDigest.",
      "files": ["crates/callisto-model/src/release.rs", "crates/callisto-model/src/lib.rs", "crates/callisto-model/tests/release_intent_test.rs"],
      "red": "Golden/permutation and negative tests first: malformed/unknown fields, digest mismatch, duplicate qualified operation identity, bare-name ecosystem collision, missing/self/cyclic prerequisites, invalid canonical order, omitted/default ambiguity, and semantic-one-field digest mutation.",
      "green": "Implement typed parsing/validation and stable Kahn ordering in model without graph/VCS/URL/provider dependencies; retain the versioned length-prefixed SHA-256 transcript.",
