    },
    {
      "id": "T04", "batch_id": "B2-intent-model", "depends_on": ["T03"], "kind": "model-security", "covers": ["009:AC-003", "009:AC-007"],
      "description": "Add durable RegistryBindingId/BindingDigest and artifact provenance coverage, ensuring the model cannot retain endpoints, credentials, raw bytes, or unclassified serialized authority fields.",
      "files": ["crates/callisto-model/src/release.rs", "crates/callisto-model/tests/release_intent_test.rs", "crates/callisto-graph/tests/release_binding_test.rs"],
      "red": "Tests prove distinct normalized bindings cannot collide, equivalent accepted bindings converge at the graph/model boundary, unsafe endpoint forms are rejected before model construction, and a serialized-field/provenance mismatch fails coverage.",
