    {
      "id": "T05", "batch_id": "B3-trust", "depends_on": ["T04"], "kind": "vcs", "covers": ["010:AC-001", "010:AC-002", "010:AC-003", "010:AC-004", "010:AC-005", "010:AC-006", "010:AC-007"],
      "description": "Expose structured VCS trust observation: canonical repository-root binding, detached exact CommitSha, clean tracked/untracked status, OS-backed release lock outside checkout, and effect-time recheck.",
      "files": ["crates/callisto-vcs/src/release_trust.rs", "crates/callisto-vcs/src/lib.rs", "crates/callisto-vcs/tests/release_trust_test.rs", "Cargo.toml", "crates/callisto-vcs/Cargo.toml"],
      "red": "Real temporary-repository tests first for non-Git/nested roots, symbolic HEAD, mismatch, dirty tracked/untracked files, lock contention/drop release, shallow/inspection failure, and changed source between validation and recheck. Recording fake adapters prove failures precede effects.",
      "green": "Use structured Git observation and typed miette errors; select a maintained OS lock crate only after checking cross-platform exclusive-lock and drop semantics. Keep lock path/handle private and non-serializable.",
      "verify": ["moon run callisto-vcs:test", "just fmt-check", "just lint"],
      "commit": "feat(vcs): bind durable releases to fresh Git trust"
    },
